 ('Hypit', 'https://x.com/ChaiWithAi/status/2109356236093415674', '开源爆款视频复刻工具，作者称首月营收可观', '让编程智能体把参考视频转为可编辑流程，复用字幕、素材和特效'),
 ('GPT-6.1 Sol', 'https://openai.com/index/asana-browser-agent', 'OpenAI GPT-6.1 系列的 Sol 型号', '用于浏览器操作等多步骤任务的 OpenAI 模型，可配合智能体工作流程'),
 ('OpenAI Daybreak', 'https://openai.com/index/sophos', 'OpenAI 安全威胁调查产品', '结合前沿模型与安全团队经验，辅助威胁调查和响应的合作计划')
), updated AS (
UPDATE public.trending_terms t SET summary_zh = v.verified_summary
FROM verified v
WHERE t.term = v.term AND t.source_url = v.source_url
AND t.summary_zh IS NOT DISTINCT FROM v.observed_summary
RETURNING t.term
)
SELECT count(*) AS summaries_restored, jsonb_agg(term ORDER BY term) AS restored_terms FROM updated;
